"""
AAF Mob Chain Resolver for UnionPlayer

Resolves MasterMob MobIDs to actual MXF file paths by:
1. Following MasterMob -> SourceMob reference
2. Extracting hex segment from SourceMob MobID (e.g., '691519a6')
3. Finding MXF files whose filename contains that hex pattern

This handles several AAF edge cases:
- "Linked media" AAF exports where Avid doesn't embed file locators
- Clips referencing external volumes (original source media paths)
- Clips where OTIO adapter stopped at MasterMob instead of following to FileSourceMob

Usage from C++:
  PythonAdapterBridge::ResolveMobPaths(aaf_path, mob_ids, search_dir) -> dict

Usage standalone:
  python resolve_aaf_mobs.py <aaf_file> <mxf_directory> [--filter SBUG]
"""

import json
import os
import sys
import re

try:
    import aaf2
except ImportError:
    print("Error: aaf2 module not found. Install with: pip install pyaaf2")
    sys.exit(1)


def extract_mxf_hex(filename):
    """
    Extract hex pattern from Avid MXF filename.

    Pattern: V02.E53A8402_69151691519ACV.mxf -> extract '69151691519ac'
    The hex after underscore and before 'V.mxf' contains the SourceMob MobID segment.
    """
    match = re.search(r'_([0-9a-fA-F]+)V\.mxf$', filename, re.IGNORECASE)
    if match:
        return match.group(1).lower()
    return None


def build_mxf_index(search_directory):
    """
    Build an index of MXF files by their hex patterns.

    Returns dict: hex_pattern -> full_path
    """
    mxf_index = {}

    if not os.path.exists(search_directory):
        return mxf_index

    for root, dirs, files in os.walk(search_directory):
        for f in files:
            if f.lower().endswith('.mxf'):
                hex_part = extract_mxf_hex(f)
                if hex_part:
                    full_path = os.path.join(root, f)
                    mxf_index[hex_part] = full_path

    return mxf_index


def resolve_mob_paths(aaf_path, mob_ids, search_directory):
    """
    Resolve MasterMob MobIDs to actual MXF file paths.

    Strategy (in order of preference):
    1. Check SourceMob locators for direct file path (most reliable)
    2. Fall back to hex pattern matching if no locator found

    The locator path is typically in Slot 2's SourceMob (RGBADescriptor).
    The path is a file:// URL that needs to be converted and relocated.

    Args:
        aaf_path: Path to the AAF file
        mob_ids: List of MobID strings (urn:smpte:umid:... format)
        search_directory: Directory to search for MXF files

    Returns:
        Dictionary mapping mob_id -> file_path (or empty string if not found)
    """
    result = {}

    # Initialize all requested mob_ids to empty (not found)
    for mob_id in mob_ids:
        result[mob_id] = ""

    if not os.path.exists(aaf_path):
        print(f"AAF file not found: {aaf_path}")
        return result

    # Build MXF file index for fallback hex matching
    mxf_index = build_mxf_index(search_directory)
    print(f"Built MXF index with {len(mxf_index)} files from {search_directory}")

    try:
        with aaf2.open(aaf_path, 'r') as f:
            # Build lookup tables
            all_mobs = {str(m.mob_id): m for m in f.content.mobs}

            # For each requested MobID
            for target_mob_id in mob_ids:
                if target_mob_id not in all_mobs:
                    continue

                mob = all_mobs[target_mob_id]
                found_path = None

                # Strategy 1: Look for locator paths in ALL slots
                for slot in getattr(mob, 'slots', []):
                    segment = getattr(slot, 'segment', None)
                    if segment is None:
                        continue

                    ref_mob_id = getattr(segment, 'mob_id', None)
                    if not ref_mob_id:
                        components = getattr(segment, 'components', None)
                        if components:
                            for comp in components:
                                ref_mob_id = getattr(comp, 'mob_id', None)
                                if ref_mob_id:
                                    break

                    if not ref_mob_id:
                        continue

                    ref_id_str = str(ref_mob_id)
                    if "00000000.00000000.00000000.00000000" in ref_id_str:
                        continue

                    if ref_id_str not in all_mobs:
                        continue

                    source_mob = all_mobs[ref_id_str]
                    descriptor = getattr(source_mob, 'descriptor', None)

                    if descriptor:
                        # Check for locator with file path
                        locators = getattr(descriptor, 'locator', None)
                        if locators:
                            for loc in locators:
                                # Get URLString from property_entries
                                props = getattr(loc, 'property_entries', {})
                                if 16385 in props:  # URLString property ID
                                    try:
                                        url = props[16385].value
                                        if url:
                                            # Convert file:// URL to local path
                                            local_path = convert_url_to_local_path(url, search_directory)
                                            if local_path and os.path.exists(local_path):
                                                found_path = local_path
                                                print(f"Resolved via locator: {mob.name} -> {os.path.basename(local_path)}")
                                                break
                                    except Exception as e:
                                        pass

                    if found_path:
                        break

                # Strategy 2: Fall back to hex pattern matching
                if not found_path and mxf_index:
                    for slot in getattr(mob, 'slots', []):
                        segment = getattr(slot, 'segment', None)
                        if segment is None:
                            continue

                        ref_mob_id = getattr(segment, 'mob_id', None)
                        if not ref_mob_id:
                            components = getattr(segment, 'components', None)
                            if components:
                                for comp in components:
                                    ref_mob_id = getattr(comp, 'mob_id', None)
                                    if ref_mob_id:
                                        break

                        if not ref_mob_id:
                            continue

                        ref_id_str = str(ref_mob_id)
                        if "00000000.00000000.00000000.00000000" in ref_id_str:
                            continue

                        # Try hex matching with SourceMob MobID
                        mxf_path = find_mxf_by_mobid(ref_id_str, mxf_index)
                        if mxf_path:
                            found_path = mxf_path
                            print(f"Resolved via hex match: {mob.name} -> {os.path.basename(mxf_path)}")
                            break

                if found_path:
                    result[target_mob_id] = found_path

    except Exception as e:
        print(f"AAF resolution error: {e}")
        import traceback
        traceback.print_exc()

    return result


def convert_url_to_local_path(url, search_directory):
    """
    Convert a file:// URL from the AAF to a local path.

    The URL is typically from a different machine (Mac), so we need to:
    1. Extract the filename from the URL
    2. Find it in the local search directory

    Example URL: file:////Users/zachkashkett/Desktop/AAFs%20for%20Chris/Avid%20MediaFiles/MXF/1/V02.E53A83DE_69151691519A0V.mxf
    """
    from urllib.parse import unquote

    # Decode URL encoding
    decoded = unquote(url)

    # Extract filename
    if '/' in decoded:
        filename = decoded.split('/')[-1]
    else:
        filename = decoded

    # Search for the file in the search directory
    for root, dirs, files in os.walk(search_directory):
        if filename in files:
            return os.path.join(root, filename)

    return None


def find_mxf_by_mobid(mob_id_str, mxf_index):
    """
    Find MXF file matching a SourceMob MobID.

    Extracts hex segment from MobID and matches against MXF filename patterns.
    MobID format: urn:smpte:umid:...691519a0.00d80000
    MXF pattern: V01.E53A83DC_686EA691519A0V.mxf

    The MXF filename hex contains the SourceMob MobID's second-to-last segment
    (e.g., '691519a0') somewhere in the hex portion after the underscore.

    IMPORTANT: We need a more precise match - the full 8-char hex segment
    should appear in the MXF hex, not just a partial match.
    """
    # Extract hex segments from MobID
    # Format: urn:smpte:umid:060a2b34.01010101.01010f00.13000000.060e2b34.7f7f2a80.691519a0.00d80000
    parts = mob_id_str.split('.')

    # Try the second-to-last segment (most specific for Avid media)
    # This is the unique identifier portion of the SourceMob MobID
    if len(parts) >= 2:
        hex_segment = parts[-2].lower()  # e.g., '691519a0'

        if len(hex_segment) >= 6:
            # Search MXF index for files containing this FULL hex segment
            for mxf_hex, mxf_path in mxf_index.items():
                # The MXF hex should contain the full segment
                # e.g., '686ea691519a0' contains '691519a0'
                if hex_segment in mxf_hex:
                    return mxf_path

    # Try the last segment if second-to-last didn't work
    if len(parts) >= 1:
        hex_segment = parts[-1].lower()
        if len(hex_segment) >= 6:
            for mxf_hex, mxf_path in mxf_index.items():
                if hex_segment in mxf_hex:
                    return mxf_path

    return None


def resolve_all_mobs(aaf_path, search_directory):
    """
    Resolve ALL MasterMobs in the AAF to their MXF file paths.

    This is the preferred method - it returns a complete map of:
    - mob_id -> mxf_path
    - clip_name -> mxf_path (for matching by name when mob_id isn't available)

    Args:
        aaf_path: Path to AAF file
        search_directory: Directory to search for MXF files

    Returns:
        Dictionary with two sub-dicts:
        {
            "by_mob_id": { mob_id -> file_path },
            "by_name": { clip_name -> file_path }
        }
    """
    result = {
        "by_mob_id": {},
        "by_name": {}
    }

    if not os.path.exists(aaf_path):
        print(f"AAF file not found: {aaf_path}")
        return result

    # Build MXF file index
    mxf_index = build_mxf_index(search_directory)
    print(f"Built MXF index with {len(mxf_index)} files from {search_directory}")

    try:
        with aaf2.open(aaf_path, 'r') as f:
            # Get all MasterMobs
            master_mobs = [m for m in f.content.mobs if isinstance(m, aaf2.mobs.MasterMob)]
            all_mobs = {str(m.mob_id): m for m in f.content.mobs}

            print(f"Found {len(master_mobs)} MasterMobs in AAF")

            for mob in master_mobs:
                mob_id_str = str(mob.mob_id)
                found_path = None

                # Strategy 1: Look for locator paths in ALL slots
                for slot in getattr(mob, 'slots', []):
                    segment = getattr(slot, 'segment', None)
                    if segment is None:
                        continue

                    ref_mob_id = getattr(segment, 'mob_id', None)
                    if not ref_mob_id:
                        components = getattr(segment, 'components', None)
                        if components:
                            for comp in components:
                                ref_mob_id = getattr(comp, 'mob_id', None)
                                if ref_mob_id:
                                    break

                    if not ref_mob_id:
                        continue

                    ref_id_str = str(ref_mob_id)
                    if "00000000.00000000.00000000.00000000" in ref_id_str:
                        continue

                    if ref_id_str not in all_mobs:
                        continue

                    source_mob = all_mobs[ref_id_str]
                    descriptor = getattr(source_mob, 'descriptor', None)

                    if descriptor:
                        # Check for locator with file path
                        locators = getattr(descriptor, 'locator', None)
                        if locators:
                            for loc in locators:
                                props = getattr(loc, 'property_entries', {})
                                if 16385 in props:  # URLString property ID
                                    try:
                                        url = props[16385].value
                                        if url:
                                            local_path = convert_url_to_local_path(url, search_directory)
                                            if local_path and os.path.exists(local_path):
                                                found_path = local_path
                                                break
                                    except Exception:
                                        pass

                    if found_path:
                        break

                # Strategy 2: Fall back to hex pattern matching
                if not found_path and mxf_index:
                    for slot in getattr(mob, 'slots', []):
                        segment = getattr(slot, 'segment', None)
                        if segment is None:
                            continue

                        ref_mob_id = getattr(segment, 'mob_id', None)
                        if not ref_mob_id:
                            components = getattr(segment, 'components', None)
                            if components:
                                for comp in components:
                                    ref_mob_id = getattr(comp, 'mob_id', None)
                                    if ref_mob_id:
                                        break

                        if not ref_mob_id:
                            continue

                        ref_id_str = str(ref_mob_id)
                        if "00000000.00000000.00000000.00000000" in ref_id_str:
                            continue

                        mxf_path = find_mxf_by_mobid(ref_id_str, mxf_index)
                        if mxf_path:
                            found_path = mxf_path
                            break

                if found_path:
                    result["by_mob_id"][mob_id_str] = found_path
                    # Also index by clip name for matching
                    if mob.name:
                        result["by_name"][mob.name.lower()] = found_path
                        print(f"Resolved: {mob.name} -> {os.path.basename(found_path)}")

    except Exception as e:
        print(f"AAF resolution error: {e}")
        import traceback
        traceback.print_exc()

    resolved_count = len(result["by_mob_id"])
    print(f"Resolved {resolved_count} clips total")
    return result


def resolve_all_mobs_json(aaf_path, search_directory):
    """
    JSON wrapper for resolve_all_mobs for C++ interop.

    Args:
        aaf_path: Path to AAF file
        search_directory: Directory to search for MXF files

    Returns:
        JSON object with by_mob_id and by_name mappings
    """
    result = resolve_all_mobs(aaf_path, search_directory)
    return json.dumps(result)


def resolve_mob_paths_json(aaf_path, mob_ids_json, search_directory):
    """
    JSON wrapper for C++ interop.

    Args:
        aaf_path: Path to AAF file
        mob_ids_json: JSON array of MobID strings
        search_directory: Directory to search for MXF files

    Returns:
        JSON object mapping mob_id -> file_path
    """
    try:
        mob_ids = json.loads(mob_ids_json)
    except json.JSONDecodeError as e:
        return json.dumps({"error": f"Invalid JSON: {e}"})

    result = resolve_mob_paths(aaf_path, mob_ids, search_directory)
    return json.dumps(result)


def main():
    """Command-line interface for testing."""
    if len(sys.argv) < 3:
        print("Usage:")
        print(f"  {sys.argv[0]} <aaf_file> <mxf_directory> [--filter <name>]")
        print()
        print("Examples:")
        print(f"  {sys.argv[0]} timeline.aaf ./Avid\\ MediaFiles/MXF/1")
        print(f"  {sys.argv[0]} timeline.aaf ./MXF --filter SBUG")
        sys.exit(1)

    aaf_path = sys.argv[1]
    mxf_dir = sys.argv[2]
    name_filter = None

    if '--filter' in sys.argv:
        idx = sys.argv.index('--filter')
        if idx + 1 < len(sys.argv):
            name_filter = sys.argv[idx + 1].lower()

    print(f"AAF: {aaf_path}")
    print(f"MXF Directory: {mxf_dir}")
    if name_filter:
        print(f"Filter: {name_filter}")
    print()

    # Build MXF index
    mxf_index = build_mxf_index(mxf_dir)
    print(f"Found {len(mxf_index)} MXF files with extractable hex patterns")
    print()

    # Open AAF and find all MasterMobs
    with aaf2.open(aaf_path, 'r') as f:
        master_mobs = [m for m in f.content.mobs if isinstance(m, aaf2.mobs.MasterMob)]

        # Collect MobIDs to resolve
        mob_ids = []
        for mob in master_mobs:
            if name_filter and name_filter not in mob.name.lower():
                continue
            mob_ids.append(str(mob.mob_id))

        print(f"Resolving {len(mob_ids)} MasterMobs...")
        print()

    # Resolve
    results = resolve_mob_paths(aaf_path, mob_ids, mxf_dir)

    # Print results
    resolved = sum(1 for v in results.values() if v)
    print()
    print(f"Results: {resolved}/{len(mob_ids)} resolved")
    print()

    if resolved > 0:
        print("Resolved paths:")
        for mob_id, path in results.items():
            if path:
                # Get mob name for display
                with aaf2.open(aaf_path, 'r') as f:
                    for mob in f.content.mobs:
                        if str(mob.mob_id) == mob_id:
                            print(f"  {mob.name}")
                            print(f"    -> {path}")
                            break


if __name__ == "__main__":
    main()
